# check raw member names for traversal/absolute/symlink entries
import tarfile
t = tarfile.open('samples/sample-batch.tar')
for m in t.getmembers():
    flags = []
    if m.issym(): flags.append(f'symlink->"{m.linkname}"')
    if m.islnk(): flags.append(f'hardlink->"{m.linkname}"')
    if m.name.startswith('/') or '..' in m.name.split('/'): flags.append('UNSAFE PATH')
    print(f"{m.type} {m.name!r} size={m.size} {' '.join(flags)}")
EOF"}
